function reducer(state, action) {
  switch (action.type) {
    case 'NAVIGATE':
      return { ...state, activeScreen: action.payload };
    case 'START_RECONCILIATION':
      return {
        ...state,
        campaignTotal: { ...state.campaignTotal, isReconciling: true }
      };
    case 'COMPLETE_RECONCILIATION':
      return {
        ...state,
        campaignTotal: {
          ...state.campaignTotal,
          isReconciling: false,
          reconciled: 403600000,
          conflicts: 213,
          ledger: [
            { cause: 'Duplicates Removed', count: 47, adj: -1200000, conf: 98 },
            { cause: 'Timing Lag Added', count: 12, adj: 250000, conf: 100 },
            { cause: 'Soft-Credit Corrected', count: 154, adj: -7450000, conf: 95 }
          ],
          humanJudgmentQueue: [
            { id: 'CON-0003', name: 'Marcus Tann', issue: 'Fuzzy match on name/grad_year', conf: 74 },
            { id: 'CON-0017', name: 'Dr. Aisha Rahman', issue: 'Stale record vs new entry', conf: 62 }
          ]
        }
      };
    case 'APPROVE_RECORD':
      return {
        ...state,
        campaignTotal: {
          ...state.campaignTotal,
          reconciled: state.campaignTotal.reconciled - 100000,
          humanJudgmentQueue: state.campaignTotal.humanJudgmentQueue.filter(q => q.id !== action.payload)
        }
      };
    case 'PUBLISH_FIGURE':
      return {
        ...state,
        campaignTotal: { ...state.campaignTotal, isPublished: true }
      };
    case 'COMPLETE_ACTION':
      return {
        ...state,
        actions: state.actions.map(a => a.id === action.payload ? { ...a, status: 'Completed' } : a)
      };
    case 'GENERATE_REPORT':
      return {
        ...state,
        readinessReport: { ...state.readinessReport, isGenerating: true }
      };
    case 'REPORT_GENERATED':
      return {
        ...state,
        readinessReport: {
          ...state.readinessReport,
          isGenerating: false,
          content: {
            summary: "The FY2026 Capital Campaign is currently tracking at $403.4M reconciled committed funds. Pipeline coverage remains strong at 3.2x, though processing dwell times in Major Gifts present a short-term forecasting risk.",
            probSuccess: 64
          }
        }
      };
    case 'UPDATE_SCENARIO':
      return {
        ...state,
        readinessReport: {
          ...state.readinessReport,
          scenario: { ...state.readinessReport.scenario, ...action.payload }
        }
      };
    case 'CONFIRM_HANDOFF':
      return {
        ...state,
        pipeline: state.pipeline.map(p => p.id === action.payload ? { ...p, handoffCandidate: false, team: 'Major Gifts' } : p)
      };
    default:
      return state;
  }
}

const Button = ({ variant = 'primary', children, onClick, disabled, loading, icon: Icon, className = '' }) => {
  const base = "rounded-input text-label flex items-center justify-center gap-2 transition-all duration-200 cursor-pointer border";
  const variants = {
    primary: "bg-[var(--accent)] text-white border-[var(--accent)] hover:bg-[var(--accent-bright)]",
    secondary: "bg-white text-[var(--ink)] border-[var(--hairline)] hover:bg-[var(--ecru)]",
    ghost: "bg-transparent text-[var(--source)] border-transparent hover:bg-[var(--wash-cool)]",
    danger: "bg-[var(--error)] text-white border-[var(--error)] hover:bg-red-700"
  };
  const disabledStyle = disabled || loading ? "opacity-50 cursor-not-allowed" : "";

  return (
    <button
      className={`${base} ${variants[variant]} ${disabledStyle} ${className}`}
      onClick={onClick}
      disabled={disabled || loading}
      style={{ padding: '8px 16px' }}
    >
      {loading ? <Activity className="animate-spin" size={16} /> : Icon && <Icon size={16} />}
      {children}
    </button>
  );
};

const Card = ({ children, className = '', onClick, style }) => (
