);

const Badge = ({ variant = 'default', children, icon: Icon }) => {
  const variants = {
    default: "bg-[var(--ecru)] text-[var(--grey)]",
    success: "bg-[var(--wash-cool)] text-[var(--source)]",
    warning: "bg-[#FDF6E3] text-[var(--gold)]",
    error: "bg-[var(--wash-warn)] text-[var(--error)]",
    accent: "bg-[var(--accent-pale)] text-[var(--accent)]"
  };
  return (
    <span className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-pill text-[11.5px] font-medium ${variants[variant]}`}>
      {Icon && <Icon size={12} />}
      {children}
    </span>
  );
};

const FormatCurrency = (val) => {
  if (!val) return '$0';
  if (val >= 1000000) return `$${(val / 1000000).toFixed(1)}M`;
  if (val >= 1000) return `$${(val / 1000).toFixed(0)}K`;
  return `$${val}`;
};

