              {reconciled ? (
                <Badge variant="error" icon={AlertTriangle}>{ct.conflicts} conflicts resolved</Badge>
              ) : (
                <Badge variant="warning" icon={AlertTriangle}>3 sources disagree</Badge>
              )}
            </div>

            <AnimatePresence mode="wait">
