                  return (
                    <motion.div
                      key={idx}
                      className="p-trail"
                      initial={{ opacity: 0, x: -10 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: 0.3 + idx * 0.1 }}
                      style={{ borderLeftColor: positive ? 'var(--source)' : 'var(--accent)' }}
                    >
                      <div className="flex items-start justify-between">
                        <div>
                          <div className="flex items-center gap-2" style={{ marginBottom: 4 }}>
                            <span className="text-body" style={{ fontWeight: 700 }}>{entry.cause}</span>
                            <Badge variant={positive ? 'success' : 'error'}>
                              {entry.count} records
                            </Badge>
                          </div>
                          <div className="text-caption" style={{ color: 'var(--grey)' }}>
                            Confidence {entry.conf}% \u00b7 {positive ? 'addition to' : 'deduction from'} reported sources
                          </div>
                        </div>
                        <div
                          className="flex items-center gap-1 text-data"
                          style={{ color: positive ? 'var(--source)' : 'var(--accent)', fontWeight: 700, fontSize: 21 }}
