        <div className="p-hitl">
          <div className="flex items-center gap-2" style={{ marginBottom: 6 }}>
            <ShieldAlert size={20} className="text-[var(--accent)]" />
            <span className="text-name" style={{ fontSize: 20 }}>Human Judgment</span>
          </div>
          <p className="text-caption" style={{ color: 'var(--grey)', marginBottom: 20 }}>
            Low-confidence matches require a human decision before they merge into the canonical total.
          </p>

          {!reconciled && (
            <div
              className="rounded-card"
              style={{ background: 'var(--pale)', border: '1px dashed var(--hairline)', padding: 20, textAlign: 'center' }}
