          {reconciled && ct.humanJudgmentQueue.length === 0 && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="rounded-card"
              style={{ background: 'var(--wash-cool)', border: '1px solid var(--source)', padding: 20, textAlign: 'center' }}
            >
              <CheckCircle2 size={22} className="text-[var(--source)]" style={{ margin: '0 auto 8px' }} />
              <div className="text-body" style={{ fontWeight: 700, color: 'var(--source)' }}>Queue cleared</div>
              <div className="text-caption" style={{ color: 'var(--grey)' }}>All contested records adjudicated.</div>
            </motion.div>
