function Screen_pipeline_board({ state, dispatch }) {
  const stages = ['Identification', 'Qualification', 'Cultivation', 'Solicitation', 'Stewardship'];

  const byStage = useMemo(() => {
    const map = {};
    stages.forEach(s => { map[s] = []; });
    state.pipeline.forEach(p => {
      if (map[p.stage]) map[p.stage].push(p);
    });
    return map;
  }, [state.pipeline]);

  const handoffCandidates = useMemo(
    () => state.pipeline.filter(p => p.handoffCandidate === true),
    [state.pipeline]
  );

  const propensityVariant = (p) => {
    if (p >= 75) return 'success';
    if (p >= 45) return 'warning';
    return 'error';
  };

  const teamColor = (team) => {
    switch (team) {
      case 'Major Gifts': return 'var(--accent)';
      case 'Annual Giving': return 'var(--source)';
      case 'Corp & Foundation': return 'var(--gold)';
      default: return 'var(--grey)';
    }
  };

  const totalPipeline = state.pipeline.reduce((sum, p) => sum + p.amount, 0);

  return (
    <div>
      <div className="p-section" style={{ marginBottom: 32 }}>
        <div className="text-kicker" style={{ marginBottom: 8 }}>Cross-Team Coordination</div>
        <h1 className="text-title" style={{ marginBottom: 12 }}>Pipeline Board</h1>
        <p className="text-body" style={{ color: 'var(--grey)', maxWidth: 720 }}>
          A shared view of the donor pipeline across all advancement teams. Track propensity scores
          by stage and resolve AI-flagged handoffs to Major Gifts.
        </p>
        <div className="flex items-center gap-8" style={{ marginTop: 20 }}>
          <div>
            <div className="text-label">Total Pipeline</div>
            <div className="text-name text-data">{FormatCurrency(totalPipeline)}</div>
          </div>
          <div style={{ width: 1, height: 40, background: 'var(--hairline)' }} />
          <div>
            <div className="text-label">Active Opportunities</div>
            <div className="text-name text-data">{state.pipeline.length}</div>
          </div>
          <div style={{ width: 1, height: 40, background: 'var(--hairline)' }} />
          <div>
            <div className="text-label">Pending Handoffs</div>
            <div className="text-name text-data" style={{ color: 'var(--accent)' }}>
              {handoffCandidates.length}
            </div>
          </div>
        </div>
      </div>

      <div style={{ marginBottom: 40 }}>
        <div className="flex items-center gap-2" style={{ marginBottom: 16 }}>
          <GitPullRequest size={18} color="var(--source)" />
          <span className="text-name" style={{ fontSize: 22 }}>Handoff Candidates</span>
          <Badge variant="accent">{handoffCandidates.length} flagged</Badge>
        </div>

        {handoffCandidates.length === 0 ? (
          <Card className="p-6">
            <div className="flex items-center gap-3" style={{ color: 'var(--grey)' }}>
              <Award size={20} color="var(--source)" />
              <span className="text-body">All handoffs resolved. No pending recommendations.</span>
            </div>
          </Card>
        ) : (
          <div className="grid" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(420px, 1fr))', gap: 20 }}>
            {handoffCandidates.map(c => (
              <motion.div
                key={c.id}
                layout
                initial={{ opacity: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                className="p-rec"
              >
                <div className="flex items-start justify-between" style={{ marginBottom: 12 }}>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="text-name" style={{ fontSize: 20 }}>{c.name}</span>
                      <Badge variant={propensityVariant(c.propensity)} icon={TrendingUp}>
                        {c.propensity}% propensity
                      </Badge>
                    </div>
                    <div className="text-caption" style={{ color: 'var(--grey)', marginTop: 4 }}>
                      {c.id} \u00b7 Currently with {c.team} \u00b7 {FormatCurrency(c.amount)}
                    </div>
                  </div>
                </div>

                <div
                  className="rounded-input"
                  style={{
                    background: 'var(--paper)',
                    border: '1px solid var(--hairline)',
                    padding: '12px 14px',
                    marginBottom: 14
                  }}
                >
                  <div className="text-label" style={{ marginBottom: 6 }}>AI Rationale</div>
                  <p className="text-caption" style={{ color: 'var(--ink)', margin: 0 }}>
                    Engagement signals and a {c.propensity}% gift propensity exceed the Major Gifts
                    threshold for the {c.stage} stage. Recommend transfer from {c.team} to a major
                    gifts officer to maximize ask capacity.
                  </p>
                </div>

                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 text-caption" style={{ color: 'var(--source)' }}>
                    <span>{c.team}</span>
                    <ArrowRight size={16} />
                    <span style={{ fontWeight: 700, color: 'var(--accent)' }}>Major Gifts</span>
                  </div>
                  <Button
                    variant="primary"
                    icon={GitPullRequest}
                    onClick={() => dispatch({ type: 'CONFIRM_HANDOFF', payload: c.id })}
