function Screen_readiness_report({ state, dispatch }) {
  const { readinessReport } = state;
  const { isGenerating, content, scenario } = readinessReport;

  useEffect(() => {
    if (isGenerating) {
      const t = setTimeout(() => dispatch({ type: 'REPORT_GENERATED' }), 1600);
      return () => clearTimeout(t);
    }
  }, [isGenerating]);

  const baseProb = content ? content.probSuccess : 64;

  const defaults = { goal: 1200000000, timeline: 12, headcount: 24 };
  const computedProb = useMemo(() => {
    let p = baseProb;
    p += (scenario.headcount - defaults.headcount) * 4;
    p += (scenario.timeline - defaults.timeline) * 2;
    p -= ((scenario.goal - defaults.goal) / 100000000) * 3;
    return Math.max(5, Math.min(98, Math.round(p)));
  }, [scenario, baseProb]);

  const headcountDelta = scenario.headcount - defaults.headcount;

  const points = useMemo(() => {
    const months = scenario.timeline;
    const goal = scenario.goal;
    const arr = [];
    for (let i = 0; i <= months; i++) {
      const frac = i / months;
      const eased = Math.pow(frac, 1.4);
      const val = goal * eased * (computedProb / 100);
      arr.push(val);
    }
    return arr;
  }, [scenario, computedProb]);

  const chartW = 900, chartH = 240, padL = 8, padR = 8, padT = 16, padB = 24;
  const maxVal = Math.max(...points, scenario.goal);
  const toX = (i) => padL + (i / (points.length - 1)) * (chartW - padL - padR);
  const toY = (v) => padT + (1 - v / maxVal) * (chartH - padT - padB);
  const linePath = points.map((v, i) => `${i === 0 ? 'M' : 'L'}${toX(i).toFixed(1)} ${toY(v).toFixed(1)}`).join(' ');
  const upper = points.map((v) => v * 1.12);
  const lower = points.map((v) => v * 0.85);
  const bandPath =
    upper.map((v, i) => `${i === 0 ? 'M' : 'L'}${toX(i).toFixed(1)} ${toY(v).toFixed(1)}`).join(' ') +
    ' ' +
    lower.slice().reverse().map((v, ri) => {
      const i = lower.length - 1 - ri;
      return `L${toX(i).toFixed(1)} ${toY(v).toFixed(1)}`;
    }).join(' ') +
    ' Z';

  const formatGoal = (v) => `$${(v / 1000000000).toFixed(2)}B`;

  const Slider = ({ label, icon: Icon, min, max, step, value, onChange, fmt }) => (
    <div className="flex flex-col gap-2" style={{ flex: 1 }}>
      <div className="flex items-center justify-between">
        <span className="text-label flex items-center gap-2" style={{ letterSpacing: '1px' }}>
          <Icon size={15} style={{ color: 'var(--muted)' }} />
          {label}
        </span>
        <span className="text-body text-data" style={{ fontWeight: 700, color: 'var(--ink)' }}>{fmt(value)}</span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(Number(e.target.value))}
        style={{ width: '100%', accentColor: 'var(--accent)', cursor: 'pointer' }}
      />
      <div className="flex justify-between text-caption" style={{ fontSize: '12px', color: 'var(--muted)' }}>
        <span>{fmt(min)}</span>
        <span>{fmt(max)}</span>
      </div>
    </div>
  );

  return (
    <div>
      <div className="mb-8 flex items-end justify-between" style={{ marginBottom: '32px' }}>
        <div>
          <div className="text-kicker mb-1">Board Briefing</div>
          <h1 className="text-title" style={{ fontSize: '40px' }}>Campaign Readiness Report</h1>
          <p className="text-body" style={{ color: 'var(--muted)', maxWidth: '640px', marginTop: '8px' }}>
            Generate the quarterly, board-grade readiness narrative and stress-test the forecast in the scenario sandbox.
          </p>
        </div>
        <Button
          variant="primary"
          icon={FileText}
          loading={isGenerating}
          onClick={() => dispatch({ type: 'GENERATE_REPORT' })}
        >
          {content ? 'Regenerate Report' : 'Generate Readiness Report'}
        </Button>
      </div>

      {!content && !isGenerating && (
        <Card className="mb-8">
          <div className="flex flex-col items-center justify-center" style={{ padding: '64px 24px', textAlign: 'center' }}>
            <FileText size={40} style={{ color: 'var(--hairline)' }} />
            <p className="text-lead" style={{ color: 'var(--muted)', marginTop: '16px' }}>
              No report generated yet.
            </p>
            <p className="text-caption" style={{ color: 'var(--muted)' }}>
              Click "Generate Readiness Report" to produce the FY2026 quarterly narrative.
            </p>
          </div>
        </Card>
      )}

      {isGenerating && (
        <Card className="mb-8">
          <div className="flex flex-col items-center justify-center" style={{ padding: '64px 24px' }}>
            <Activity className="animate-spin" size={32} style={{ color: 'var(--accent)' }} />
            <p className="text-lead" style={{ color: 'var(--ink)', marginTop: '16px' }}>
              Composing readiness narrative\u2026
            </p>
            <p className="text-caption" style={{ color: 'var(--muted)' }}>
              Reconciling pipeline coverage, KPI trends, and operational gaps.
            </p>
          </div>
        </Card>
      )}

      {content && !isGenerating && (
        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4 }}
        >
          <Card className="mb-8">
            <div style={{ padding: '28px 32px' }}>
              <div className="flex items-center justify-between mb-4">
                <div className="text-label" style={{ color: 'var(--accent)' }}>Executive Summary \u00b7 FY2026</div>
                <Badge variant="success" icon={Check}>Reconciled basis</Badge>
              </div>
              <p className="text-lead" style={{ color: 'var(--ink)', lineHeight: 1.5 }}>
                {content.summary}
              </p>
              <div className="flex items-center gap-3" style={{ marginTop: '24px', paddingTop: '20px', borderTop: '1px solid var(--hairline)' }}>
                <Target size={20} style={{ color: 'var(--source)' }} />
                <span className="text-body">
                  Baseline probability of campaign success:&nbsp;
                  <strong className="text-data" style={{ color: 'var(--source)' }}>{content.probSuccess}%</strong>
                </span>
              </div>
            </div>
          </Card>

          <div className="p-forecast-band">
            <div className="flex items-center justify-between mb-4">
              <div>
                <div className="text-label" style={{ color: 'var(--muted)' }}>Projected Committed Funds</div>
                <div className="text-name" style={{ fontSize: '22px' }}>
                  {formatGoal(scenario.goal)} <span className="text-caption" style={{ color: 'var(--muted)' }}>over {scenario.timeline} months</span>
                </div>
              </div>
              <Badge variant="accent" icon={TrendingUp}>{computedProb}% likelihood band</Badge>
            </div>
            <svg viewBox={`0 0 ${chartW} ${chartH}`} width="100%" style={{ display: 'block' }} aria-hidden="true">
              {[0.25, 0.5, 0.75, 1].map((g, i) => (
                <line key={i}
                  x1={padL} x2={chartW - padR}
                  y1={toY(maxVal * g)} y2={toY(maxVal * g)}
                  stroke="var(--hairline)" strokeWidth="1" strokeDasharray="2 4"
                />
              ))}
              <path d={bandPath} fill="var(--wash-cool)" opacity="0.7" />
              <line x1={padL} x2={chartW - padR} y1={toY(scenario.goal)} y2={toY(scenario.goal)}
                stroke="var(--accent)" strokeWidth="1.5" strokeDasharray="6 4" />
              <motion.path
                key={linePath}
                d={linePath}
                fill="none"
                stroke="var(--source)"
                strokeWidth="2.5"
                strokeLinecap="round"
                initial={{ pathLength: 0 }}
                animate={{ pathLength: 1 }}
                transition={{ duration: 0.8 }}
              />
              <circle cx={toX(points.length - 1)} cy={toY(points[points.length - 1])} r="5" fill="var(--source)" />
            </svg>
            <div className="flex items-center justify-between text-caption" style={{ color: 'var(--muted)', marginTop: '8px' }}>
              <span>Goal target (dashed) \u00b7 Projected trajectory (solid) \u00b7 Confidence envelope (shaded)</span>
              <span className="text-data">Proj. close: {FormatCurrency(points[points.length - 1])}</span>
            </div>
          </div>

          <div className="p-time-machine">
            <div className="flex items-center gap-2">
              <Clock size={18} style={{ color: 'var(--accent)' }} />
              <span className="text-name" style={{ fontSize: '20px' }}>Scenario Sandbox</span>
            </div>
            <p className="text-caption" style={{ color: 'var(--muted)', margin: 0 }}>
              Adjust the campaign parameters to model alternative readiness paths.
            </p>
            <div className="flex gap-8" style={{ marginTop: '8px', flexWrap: 'wrap' }}>
              <Slider
                label="Campaign Goal" icon={Target}
                min={800000000} max={1600000000} step={50000000}
                value={scenario.goal}
                onChange={(v) => dispatch({ type: 'UPDATE_SCENARIO', payload: { goal: v } })}
                fmt={formatGoal}
              />
              <Slider
                label="Timeline (months)" icon={Clock}
                min={6} max={24} step={1}
                value={scenario.timeline}
                onChange={(v) => dispatch({ type: 'UPDATE_SCENARIO', payload: { timeline: v } })}
                fmt={(v) => `${v}mo`}
              />
              <Slider
                label="Headcount (officers)" icon={Users}
                min={12} max={40} step={1}
                value={scenario.headcount}
                onChange={(v) => dispatch({ type: 'UPDATE_SCENARIO', payload: { headcount: v } })}
                fmt={(v) => `${v}`}
              />
            </div>
          </div>

          <div className="p-counterfactual" style={{ marginBottom: '24px' }}>
            <div className="flex items-center gap-2 mb-1">
              <Activity size={16} style={{ color: 'var(--source)' }} />
              <span className="text-label" style={{ color: 'var(--source)', letterSpacing: '1px' }}>Counterfactual</span>
            </div>
            <p className="text-lead" style={{ margin: 0, color: 'var(--ink)' }}>
              {headcountDelta !== 0 ? (
                <>
                  {headcountDelta > 0 ? 'Increasing' : 'Reducing'} headcount by{' '}
                  <strong>{Math.abs(headcountDelta)}</strong> shifts probability of success from{' '}
                  <strong className="text-data">{baseProb}%</strong> to{' '}
                  <strong className="text-data" style={{ color: computedProb >= baseProb ? 'var(--success)' : 'var(--error)' }}>
                    {computedProb}%
                  </strong>.
                </>
              ) : (
                <>
                  At baseline staffing, probability of success holds at{' '}
                  <strong className="text-data" style={{ color: computedProb >= baseProb ? 'var(--success)' : 'var(--error)' }}>
                    {computedProb}%
                  </strong> under the current goal and timeline.
                </>
              )}
            </p>
          </div>

          <div className="p-kpi" style={{ marginBottom: 0 }}>
            {[
              { label: 'Probability of Success', val: `${computedProb}%`, sub: `baseline ${baseProb}%`, color: computedProb >= baseProb ? 'var(--success)' : 'var(--error)' },
              { label: 'Pipeline Coverage', val: '3.2\u00d7', sub: 'vs 3.0\u00d7 target', color: 'var(--source)' },
              { label: 'Reconciled Committed', val: '$403.4M', sub: `of ${formatGoal(scenario.goal)} goal`, color: 'var(--ink)' },
              { label: 'Officers Required', val: `${scenario.headcount}`, sub: `${scenario.timeline}mo horizon`, color: 'var(--ink)' }
            ].map((s, i) => (
              <Card key={i}>
                <div style={{ padding: '20px 22px' }}>
                  <div className="text-label" style={{ color: 'var(--muted)' }}>{s.label}</div>
                  <div className="text-display text-data" style={{ fontSize: '38px', color: s.color, marginTop: '6px' }}>{s.val}</div>
                  <div className="text-caption" style={{ color: 'var(--muted)', marginTop: '4px' }}>{s.sub}</div>
                </div>
              </Card>
            ))}
          </div>
        </motion.div>
      )}
    </div>
  );
}

function Screen_action_log({ state, dispatch }) {
  const today = new Date('2025-10-08');

  const enriched = useMemo(() => state.actions.map(a => {
    const dueDate = new Date(a.due);
    const overdue = dueDate < today && a.status !== 'Completed';
    const atRisk = !overdue && a.risk === 'high' && a.status !== 'Completed';
    return { ...a, overdue, atRisk, dueDate };
  }), [state.actions]);

  const open = enriched.filter(a => a.status !== 'Completed');
  const completed = enriched.filter(a => a.status === 'Completed');

  const slipRisk = (a) => {
    if (a.overdue) return { pct: 95, label: 'Critical slip risk' };
    if (a.atRisk) return { pct: 72, label: 'Elevated slip risk' };
    if (a.risk === 'low') return { pct: 18, label: 'Low slip risk' };
    return { pct: 40, label: 'Moderate slip risk' };
  };

  const fmtDate = (d) => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

  const ActionItem = ({ a }) => {
    const risk = slipRisk(a);
    const done = a.status === 'Completed';
    return (
      <motion.div
        layout
        initial={{ opacity: 0, y: 8 }}
        animate={{ opacity: 1, y: 0 }}
        className="p-trail"
        style={{
          borderLeftColor: done ? 'var(--success)' : a.overdue ? 'var(--error)' : a.atRisk ? 'var(--gold)' : 'var(--hairline)',
          borderLeftWidth: '3px'
        }}
      >
        <Card className="p-5">
          <div className="flex items-start justify-between gap-6">
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 mb-2">
                <span className="text-label" style={{ letterSpacing: '1.5px' }}>{a.id}</span>
                {done && <Badge variant="success" icon={CheckCircle2}>Completed</Badge>}
                {a.overdue && <Badge variant="error" icon={AlertTriangle}>Overdue</Badge>}
                {a.atRisk && <Badge variant="warning" icon={AlertTriangle}>At Risk</Badge>}
                {!done && !a.overdue && !a.atRisk && <Badge variant="default" icon={Clock}>On Track</Badge>}
              </div>

              <p className="text-body" style={{ color: 'var(--ink)', fontWeight: 500, marginBottom: '12px' }}>
                {a.desc}
              </p>

              <div className="flex items-center gap-6 flex-wrap mb-4">
                <span className="flex items-center gap-1.5 text-caption" style={{ color: 'var(--grey)' }}>
                  <Users size={15} /> {a.owner}
                </span>
                <span className="flex items-center gap-1.5 text-caption" style={{ color: a.overdue ? 'var(--error)' : 'var(--grey)' }}>
                  <Clock size={15} /> Due {fmtDate(a.dueDate)}
                </span>
              </div>

              {!done && (
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-caption" style={{ color: 'var(--grey)', display: 'flex', alignItems: 'center', gap: '6px' }}>
                      <Activity size={14} /> {risk.label}
                    </span>
                    <span className="text-caption text-data" style={{ color: risk.pct >= 70 ? 'var(--error)' : risk.pct >= 40 ? 'var(--gold)' : 'var(--source)', fontWeight: 700 }}>
                      {risk.pct}%
                    </span>
                  </div>
                  <div style={{ height: '6px', background: 'var(--ecru)', borderRadius: '999px', overflow: 'hidden' }}>
                    <motion.div
                      initial={{ width: 0 }}
                      animate={{ width: `${risk.pct}%` }}
                      transition={{ duration: 0.6 }}
                      style={{
                        height: '100%',
                        borderRadius: '999px',
                        background: risk.pct >= 70 ? 'var(--error)' : risk.pct >= 40 ? 'var(--gold)' : 'var(--source)'
                      }}
                    />
                  </div>
                </div>
              )}
            </div>

            <div className="flex-shrink-0">
              {!done ? (
                <Button variant="primary" icon={CheckCircle2} onClick={() => dispatch({ type: 'COMPLETE_ACTION', payload: a.id })}>
                  Mark Complete
                </Button>
              ) : (
                <span className="flex items-center gap-2 text-caption" style={{ color: 'var(--success)' }}>
                  <CheckCircle2 size={18} /> Closed
                </span>
              )}
            </div>
          </div>
        </Card>
      </motion.div>
    );
  };

  const openRisk = open.filter(a => a.overdue || a.atRisk).length;

  return (
    <div>
      <div className="p-section">
        <span className="text-kicker">Cross-Team Alignment</span>
        <h1 className="text-title" style={{ marginTop: '8px', marginBottom: '12px' }}>Action Log</h1>
        <p className="text-lead" style={{ color: 'var(--grey)', maxWidth: '720px' }}>
          Track inter-team decisions through to closure. Slip-risk predictions flag follow-through
          most likely to fall behind before campaign deadlines.
        </p>
      </div>

      <div className="p-kpi">
        <Card className="p-6">
          <div className="text-label">Open Actions</div>
          <div className="text-name text-data" style={{ marginTop: '8px' }}>{open.length}</div>
        </Card>
        <Card className="p-6">
          <div className="text-label">Flagged At Risk / Overdue</div>
          <div className="text-name text-data" style={{ marginTop: '8px', color: openRisk ? 'var(--error)' : 'var(--ink)' }}>{openRisk}</div>
        </Card>
        <Card className="p-6">
          <div className="text-label">Completed</div>
          <div className="text-name text-data" style={{ marginTop: '8px', color: 'var(--success)' }}>{completed.length}</div>
        </Card>
      </div>

      <div className="p-multi">
        <div className="flex items-center gap-3 mb-2">
          <h2 className="text-name">Active</h2>
          <Badge variant="accent">{open.length}</Badge>
        </div>
        {open.length === 0 ? (
          <Card className="p-6">
            <p className="text-body" style={{ color: 'var(--grey)' }}>All actions closed. No outstanding alignment items.</p>
          </Card>
        ) : open.map(a => <ActionItem key={a.id} a={a} />)}

        {completed.length > 0 && (
          <>
            <div className="flex items-center gap-3 mb-2 mt-8">
              <h2 className="text-name">Closed</h2>
              <Badge variant="success">{completed.length}</Badge>
            </div>
            {completed.map(a => <ActionItem key={a.id} a={a} />)}
          </>
        )}
      </div>
    </div>
  );
}

function App() {
  const [state, dispatch] = useReducer(reducer, initialState);

  const navItems = [
    { id: 'home', icon: LayoutDashboard, label: 'Home' },
    { id: 'reconciliation', icon: GitMerge, label: 'Reconcile' },
    { id: 'kpi-scorecard', icon: Target, label: 'KPIs' },
    { id: 'pipeline-board', icon: Users, label: 'Pipeline' },
    { id: 'readiness-report', icon: FileText, label: 'Report' },
    { id: 'action-log', icon: CheckCircle2, label: 'Actions' }
  ];

  return (
    <div className="app-container">
      <style>{styles}</style>

      <nav className="nav-rail">
        <div className="mb-8">
          <NLogo />
        </div>
        <div className="flex flex-col gap-6 w-full items-center">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => dispatch({ type: 'NAVIGATE', payload: item.id })}
              className={`p-3 rounded-card transition-colors ${state.activeScreen === item.id ? 'bg-[var(--ink)] text-white' : 'text-[var(--grey)] hover:bg-[var(--ink)] hover:text-white'}`}
              title={item.label}
            >
              <item.icon size={24} />
            </button>
          ))}
        </div>
      </nav>

      <main className="main-content">
        <header className="masthead">
          <div className="flex items-center gap-4">
            <span className="text-title" style={{ fontSize: '24px' }}>Advancement Alignment Cockpit</span>
          </div>
          <div className="flex items-center gap-4">
            <Badge icon={Lock}>Northeastern University \u00b7 FY2026 Campaign</Badge>
          </div>
        </header>

        <div className="workspace">
          {state.activeScreen === 'home' && <Screen_home state={state} dispatch={dispatch} />}
          {state.activeScreen === 'reconciliation' && <Screen_reconciliation state={state} dispatch={dispatch} />}
          {state.activeScreen === 'kpi-scorecard' && <Screen_kpi_scorecard state={state} dispatch={dispatch} />}
          {state.activeScreen === 'pipeline-board' && <Screen_pipeline_board state={state} dispatch={dispatch} />}
          {state.activeScreen === 'readiness-report' && <Screen_readiness_report state={state} dispatch={dispatch} />}
          {state.activeScreen === 'action-log' && <Screen_action_log state={state} dispatch={dispatch} />}
        </div>
      </main>
    </div>
  );
}
